package com.punjab.oms.ar.dao.finance;
import org.flywaydb.core.Flyway;import org.flywaydb.core.api.FlywayException;import org.flywaydb.core.api.configuration.FluentConfiguration;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.junit.jupiter.api.io.TempDir;
import java.sql.*;import java.nio.file.*;import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-migration creates disposable schemas; never uses oms_ar/oms_ar_test. @author Punjab */
@EnabledIfSystemProperty(named="ar.migration.real",matches="true") @EnabledIfSystemProperty(named="ar.migration.real.commit",matches="true")
class MigrationRealTest {
 @TempDir Path temp;
 String database(String suffix){String prefix=System.getenv("AR_MIGRATION_DATABASE_PREFIX");assertThat(prefix).matches("oms_ar_migration_[a-f0-9]{12}");return prefix+"_"+suffix;}
 String url(String suffix){return "jdbc:mysql://127.0.0.1:13306/"+database(suffix);}
 FluentConfiguration config(String suffix){return Flyway.configure().dataSource(url(suffix),"oms_ar",System.getenv("AR_TEST_PASSWORD")).locations("classpath:db/migration").baselineOnMigrate(false).cleanDisabled(true).validateOnMigrate(true);}
 Connection connection(String suffix)throws Exception{return DriverManager.getConnection(url(suffix),"oms_ar",System.getenv("AR_TEST_PASSWORD"));}
 long number(String suffix,String sql)throws Exception{try(var c=connection(suffix);var s=c.createStatement();var rs=s.executeQuery(sql)){rs.next();return rs.getLong(1);}}
 void execute(String suffix,String sql)throws Exception{try(var c=connection(suffix);var s=c.createStatement()){s.execute(sql);}}
 void copyMigrations()throws Exception{try(var files=Files.list(Path.of("src/main/resources/db/migration"))){for(var file:files.toList())Files.copy(file,temp.resolve(file.getFileName()));}}
 @Test @DisplayName("空库全部迁移，重复运行无改动，clean被禁止")void fresh()throws Exception{var flyway=config("fresh").load();assertThat(flyway.migrate().migrationsExecuted).isEqualTo(15);assertThat(flyway.info().current().getVersion().toString()).isEqualTo("015");assertThat(number("fresh","SELECT COUNT(*) FROM flyway_schema_history WHERE success=1")).isEqualTo(15);assertThat(flyway.migrate().migrationsExecuted).isZero();String insert="INSERT INTO oms_ar_cash_account(customer_id,legal_entity_id,currency,invoice_mode,created_by,updated_by) VALUES(9,1,'CNY','%s','test','test')";
 execute("fresh",insert.formatted("INVOICE"));execute("fresh",insert.formatted("NO_INVOICE"));
 assertThatThrownBy(()->execute("fresh",insert.formatted("INVOICE"))).isInstanceOf(SQLException.class);
 assertThatThrownBy(()->execute("fresh","UPDATE oms_ar_cash_account SET frozen_amount=1 WHERE customer_id=9")).isInstanceOf(SQLException.class);
 assertThat(number("fresh","SELECT COUNT(*) FROM oms_ar_cash_account WHERE customer_id=9 AND available_amount=0")).isEqualTo(2);
 execute("fresh","INSERT INTO oms_ar_business_group(group_no,customer_id,legal_entity_id,currency,business_date,created_by,updated_by) VALUES ('G1',9,1,'CNY',CURRENT_DATE(),'test','test'),('G2',10,1,'CNY',CURRENT_DATE(),'test','test')");
 String binding="INSERT INTO oms_ar_cash_group_binding(group_id,cash_account_id,customer_id,legal_entity_id,currency,created_time,updated_time,created_by,updated_by) SELECT g.id,a.id,g.customer_id,g.legal_entity_id,g.currency,NOW(),NOW(),'test','test' FROM oms_ar_business_group g JOIN oms_ar_cash_account a ON a.invoice_mode='%s' WHERE g.group_no='%s'";
 execute("fresh",binding.formatted("INVOICE","G1"));
 assertThatThrownBy(()->execute("fresh",binding.formatted("NO_INVOICE","G1"))).isInstanceOf(SQLException.class);
 assertThatThrownBy(()->execute("fresh",binding.formatted("INVOICE","G2"))).isInstanceOf(SQLException.class);
 flyway.validate();assertThatThrownBy(flyway::clean).isInstanceOf(FlywayException.class);assertThat(number("fresh","SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='oms_ar_outbox_retry'")).isEqualTo(1);}
 @Test @DisplayName("从V6升级到完整版本且保留原数据")void upgrade()throws Exception{assertThat(config("upgrade").target("6").load().migrate().migrationsExecuted).isEqualTo(6);execute("upgrade","INSERT INTO oms_ar_receipt(customer_id,legal_entity_id,currency,amount,received_date,source_system,source_id,source_no,created_time,created_by,updated_time,updated_by) VALUES(1,1,'CNY',123.45,CURRENT_DATE(),'MIGRATION','keep','keep',NOW(6),'test',NOW(6),'test')");assertThat(config("upgrade").load().migrate().migrationsExecuted).isEqualTo(9);assertThat(number("upgrade","SELECT COUNT(*) FROM oms_ar_receipt WHERE source_id='keep' AND amount=123.45")).isEqualTo(1);config("upgrade").load().validate();}
 @Test @DisplayName("已执行文件发生修改时拒绝校验及继续迁移")void checksum()throws Exception{assertThat(config("tamper").load().migrate().migrationsExecuted).isEqualTo(15);copyMigrations();var first=temp.resolve("V001__ar_core.sql");Files.writeString(first,Files.readString(first).replace("VARCHAR(64)","VARCHAR(63)"));var changed=config("tamper").locations("filesystem:"+temp).load();assertThatThrownBy(changed::validate).isInstanceOf(FlywayException.class).hasMessageContaining("checksum mismatch");assertThatThrownBy(changed::migrate).isInstanceOf(FlywayException.class);assertThat(number("tamper","SELECT COUNT(*) FROM flyway_schema_history WHERE success=1")).isEqualTo(15);}
 @Test @DisplayName("无迁移历史的非空库不能自动接管")void unmanaged()throws Exception{execute("unmanaged","CREATE TABLE existing_data(id INT PRIMARY KEY)");execute("unmanaged","INSERT INTO existing_data VALUES(7)");assertThatThrownBy(()->config("unmanaged").load().migrate()).isInstanceOf(FlywayException.class).hasMessageContaining("non-empty");assertThat(number("unmanaged","SELECT id FROM existing_data")).isEqualTo(7);assertThat(number("unmanaged","SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='oms_ar_document'")).isZero();}
 @Test @DisplayName("DDL部分失败后保留失败记录并拒绝自动继续")void failed()throws Exception{assertThat(config("failure").load().migrate().migrationsExecuted).isEqualTo(15);copyMigrations();Files.writeString(temp.resolve("V016__intentional_failure.sql"),"CREATE TABLE migration_partial(id INT); INSERT INTO nonexistent_migration_table VALUES(1);");var broken=config("failure").locations("filesystem:"+temp).load();assertThatThrownBy(broken::migrate).isInstanceOf(FlywayException.class);assertThat(number("failure","SELECT COUNT(*) FROM flyway_schema_history WHERE success=0")).isEqualTo(1);assertThat(number("failure","SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='migration_partial'")).isEqualTo(1);assertThatThrownBy(broken::migrate).isInstanceOf(FlywayException.class).hasMessageContaining("failed migration");}
}
